bool Decode(const nlohmann::json& v, canon::json::Decoder& dec, Shape& out) {
    if (!canon::json::detail::Object(v, dec)) return false;
    std::string tag;
    if (!dec.String(v, "kind", tag)) return false;
    if (tag == "circle") {
        Decode(v, dec, out.value_.emplace<0>());
    } else if (tag == "DOT") {
        out.value_.emplace<1>();
    } else {
        dec.Fail("kind", "unknown case " + tag);
    }
    return dec.Ok();
}

