std::optional<Shape> Shape::Decode(const nlohmann::json& v, std::string& error) {
    canon::json::Decoder dec("Shape");
    dec.Push("$");
    std::optional<Shape> out;
    if (detail::Decode(v, dec, out.emplace())) return out;
    error = dec.Error();
    return std::nullopt;
}

std::optional<Shape> Shape::Parse(std::string_view text, std::string& error) {
    nlohmann::json doc;
    canon::json::Float32Tokens tokens;
    canon::json::KeyOrders orders;
    if (!canon::json::ParseTextFile("Shape", text, doc, error, tokens, orders)) return std::nullopt;
    canon::json::Decoder dec("Shape", tokens, orders);
    dec.Push("$");
    std::optional<Shape> out;
    if (detail::Decode(doc, dec, out.emplace())) return out;
    error = dec.Error();
    return std::nullopt;
}

